function StandardLoesung({m,schemaOeffnen}){return <div className="fall__block"><b>Lösung</b><ol>{(m.example?.solution||[]).map((s,i)=><li key={i}><AOVerlinkterText text={s} onOpen={schemaOeffnen} compact/></li>)}</ol><AONormkette normen={m.normchain||[]} onOpen={schemaOeffnen}/></div>}
function FallLoesung({m,schemaOeffnen}){if(m.id===320||m.id===321)return <AOFallEinheit2Darstellung fallId={m.id} onSchema={schemaOeffnen}/>;if(m.id===334)return <AOFall334Darstellung onSchema={schemaOeffnen}/>;if((m.einheit===5||m.einheit===6||m.einheit===7)&&m.diagram)return <AOSchema id={m.diagram}/>;return <StandardLoesung m={m} schemaOeffnen={schemaOeffnen}/>}
function AOSeite({m,erledigt,umschalten,zurueck,oeffnen,schemaOeffnen,hausaufgabenOeffnen}){const fertig=erledigt.includes(m.id),liste=m.area==="Fall"?AO_FAELLE:AO_MODULE,index=liste.findIndex(x=>x.id===m.id),vorher=liste[index-1],nachher=liste[index+1],istFall=m.area==="Fall";let tz=0;const n=()=>++tz;return <article className="lesson ao-lesson"><button className="zurueck" onClick={zurueck}>← Zurück zur AO-Übersicht</button><header className="lesson__kopf"><div><span className="kicker">Klausur 1 · Abgabenordnung · {istFall?"Originalfall":"Lernmodul"} {m.id}</span><h1>{m.title}</h1><div className="tags"><PrioBadge prio={prioInhalt(m)} mitThema/><span className="tag tag--fach">{m.difficulty}</span><span className="tag">{m.minutes} Minuten</span><span className="tag">AO Einheit {m.einheit} · PDF-S. {m.sourcePages?.join(", ")}</span></div><p className="ao-lawline">{m.law}</p><AOSchemaVerweise text={m.law} onOpen={schemaOeffnen}/></div><button className="gemeistert" aria-pressed={fertig} onClick={()=>umschalten(m.id)}>{fertig?"✓ bearbeitet":"Als bearbeitet markieren"}</button></header><Tz nummer={n()} label="Einordnung" titel="Worum es geht">{(m.intro||[]).map((p,i)=><AOVerlinkterText key={i} as="p" text={p} onOpen={schemaOeffnen} compact/>)}</Tz><Tz nummer={n()} label="Lernziele" titel="Das können Sie danach"><ul className="liste liste--haken">{(m.goals||[]).map((g,i)=><li key={i}><AOVerlinkterText text={g} onOpen={schemaOeffnen} compact/></li>)}</ul></Tz><Tz nummer={n()} label="Schema" titel="Prüfungsreihenfolge" art="ansatz"><ol className="schritte">{(m.scheme||[]).map((s,i)=><li key={i}><AOVerlinkterText text={s} onOpen={schemaOeffnen} compact/></li>)}</ol>{m.diagram&&<AOSchema id={m.diagram}/>}</Tz><Tz nummer={n()} label="Normen" titel="Normenkette für die Klausur"><AONormkette normen={m.normchain||[]} onOpen={schemaOeffnen}/></Tz>{m.example&&<Tz nummer={n()} label={istFall?"Originalfall":"Vertiefung"} titel={m.example.title} art="bewertung"><div className="fall"><div className="fall__block fall__sachverhalt"><b>{istFall?"Sachverhalt / Aufgabenstellung":"Ausgangspunkt"}</b><AOVerlinkterText as="p" text={m.example.facts} onOpen={schemaOeffnen} compact/></div>{istFall?<FallLoesung m={m} schemaOeffnen={schemaOeffnen}/>:<StandardLoesung m={m} schemaOeffnen={schemaOeffnen}/>}<div className="fall__block fall__ergebnis"><b>Ergebnis</b><AOVerlinkterText as="p" text={m.example.result} onOpen={schemaOeffnen} compact/></div></div></Tz>}<AOHausaufgabenHinweise moduleId={m.id} onOpenHausaufgabe={hausaufgabenOeffnen}/><Tz nummer={n()} label="Sichern" titel="Merksatz, Prüfungsrelevanz und Fallen"><div className="notiz"><p>{m.merksatz}</p></div>{m.exam?.length>0&&<div className="notiz notiz--exkurs"><b>Prüfungsrelevanz / Quelle</b><ul>{m.exam.map((e,i)=><li key={i}>{e}</li>)}</ul></div>}{m.traps?.length>0&&<div className="notiz notiz--falle"><b>Typische Fallen</b><ul>{m.traps.map((t,i)=><li key={i}>{t}</li>)}</ul></div>}</Tz><Tz nummer={n()} label="Quellen" titel="Fundstellen und Quellenstand"><ul className="liste"><li>AO Einheit {m.einheit} · PDF-S. {m.sourcePages?.join(", ")}</li><li>Tabellen, Schemata, Zeitachsen, Handbuch-Reiter und Merkkarten der zugeordneten Seiten werden in ihrer jeweiligen Darstellungsart digital übernommen.</li><li>Maßgebliche Normen laut Einheit: {m.law}</li></ul></Tz><nav className="blaettern">{vorher?<button onClick={()=>oeffnen(vorher.id)}><small>← {vorher.area==="Fall"?"Fall":"Modul"} {vorher.id}</small><strong>{vorher.title}</strong></button>:<span/>}{nachher?<button onClick={()=>oeffnen(nachher.id)}><small>{nachher.area==="Fall"?"Fall":"Modul"} {nachher.id} →</small><strong>{nachher.title}</strong></button>:<span/>}</nav></article>}
function AOCockpit({erledigt,oeffnen,ansichtOeffnen,schemaOeffnen}){const modulErledigt=AO_MODULE.filter(m=>erledigt.includes(m.id)).length,fallErledigt=AO_FAELLE.filter(m=>erledigt.includes(m.id)).length,naechstes=AO_MODULE.find(m=>!erledigt.includes(m.id))||AO_MODULE[0];return <><div className="cockpit"><section className="these kst-these"><span className="kicker">Klausur 1 · Verfahrensrecht · Abgabenordnung</span><h2>AO systematisch: <em>Verfahren → VA → Rechtsbehelf → Korrektur → Strafrecht/Haftung.</em></h2><p>Die AO-Einheiten 1–8 sind vollständig eingearbeitet: {AO_SEITEN} PDF-Seiten/Frames, {AO_MODULE.length} Lernmodule und {AO_FAELLE.length} kursinterne Originalfälle. Tabellen bleiben Tabellen; Schemata, Zeitachsen und Quellen-Fragezeichen werden quellengetreu als digitale Lernbilder nachgebaut.</p><div className="these__aktionen"><button className="btn" onClick={()=>oeffnen(naechstes.id)}>Weiterlernen</button><button className="btn btn--linie" onClick={()=>ansichtOeffnen("faelle")}>Originalfälle</button><button className="btn btn--linie" onClick={()=>schemaOeffnen("ao-schema-ablauf")}>Prüfschema</button></div></section><section className="panel fortschritt"><div className="ao-ring-row"><div className="ring" style={{"--p":`${anteil(modulErledigt,AO_MODULE.length)}%`}}><b>{anteil(modulErledigt,AO_MODULE.length)}%</b></div><div><h3>Lernmodule</h3><p>{modulErledigt} / {AO_MODULE.length}</p></div></div><div className="ao-ring-row"><div className="ring" style={{"--p":`${anteil(fallErledigt,AO_FAELLE.length)}%`}}><b>{anteil(fallErledigt,AO_FAELLE.length)}%</b></div><div><h3>Originalfälle</h3><p>{fallErledigt} / {AO_FAELLE.length}</p></div></div></section></div><section className="abschnitt"><span className="kicker">Weiter im Stoff</span><button className="weiter" onClick={()=>oeffnen(naechstes.id)}><span className="kicker">Lernmodul {naechstes.id} · {oberVon(naechstes).label}</span><PrioBadge prio={prioInhalt(naechstes)}/><h3>{naechstes.title}</h3><p>{naechstes.intro?.[0]}</p><span className="norm">{naechstes.law}</span></button></section><section className="abschnitt"><div className="kst-abschnitt-kopf"><div><span className="kicker">Oberthemen</span><h2>AO Einheiten 1–8</h2></div></div><div className="ao-cockpit-topics">{OBER.filter(o=>o.id!=="alle").map(o=><button key={o.id} onClick={()=>ansichtOeffnen("module",o.id)}><b>{o.label}</b><span>{o.beschreibung}</span><small>{o.module.length} Unterthemen →</small></button>)}</div></section><PrioCockpit fach="ao" zaehlung={PRIO_ZAEHLUNG}/><section className="abschnitt"><div className="kst-abschnitt-kopf"><h2>Grundschema des Besteuerungsverfahrens</h2><button className="kst-schema-alle" onClick={()=>schemaOeffnen("ao-schema-ablauf")}>Gesamtes AO-Prüfschema ↗</button></div><AOSchema id="ao-besteuerungsverfahren"/></section></>}
function AOThemenseite({suche,ober,setOber,prio,setPrio,erledigt,umschalten,oeffnen,schemaOeffnen}){const q=suche.trim().toLowerCase(),basis=ober==="alle"?AO_MODULE:AO_MODULE.filter(m=>oberVon(m).id===ober),liste=basis.filter(m=>(prio==="alle"||prioInhalt(m).stufe===prio)&&(!q||[m.title,m.law,...(m.intro||[]),...(m.goals||[]),...(m.scheme||[])].join(" ").toLowerCase().includes(q))),aktiv=OBER.find(o=>o.id===ober)||OBER[0];return <><div className="pagehead"><div><span className="kicker">Klausur 1 · Abgabenordnung · Lernmodule</span><h1>{suche?`Treffer für „${suche}“`:aktiv.id==="alle"?"AO-Lernmodule nach Oberthemen":aktiv.label}</h1><p className="lead">Die Kurs-Einheit bleibt Quellenmetadatum; gelernt wird nach fachlichen Oberthemen.</p></div><span className="zaehler">{liste.length} Unterthemen</span></div><div className="filter ao-topic-filter">{OBER.map(o=><button key={o.id} aria-pressed={ober===o.id} onClick={()=>setOber(o.id)}>{o.label}</button>)}</div><PrioFilter wert={prio} setWert={setPrio} zaehlung={PRIO_ZAEHLUNG}/>{aktiv.id!=="alle"&&<div className="ao-topic-intro"><span className="kicker">Oberthema</span><h2>{aktiv.label}</h2><p>{aktiv.beschreibung}</p></div>}<div className="modules">{liste.map(m=>{const fertig=erledigt.includes(m.id);return <div key={m.id} className={`modul${fertig?" modul--fertig":""}`} role="button" tabIndex={0} onClick={()=>oeffnen(m.id)} onKeyDown={e=>(e.key==="Enter"||e.key===" ")&&(e.preventDefault(),oeffnen(m.id))}><span className="modul__check" role="checkbox" aria-checked={fertig} tabIndex={0} onClick={e=>{e.stopPropagation();umschalten(m.id)}}><IconHaken/></span><div><div className="modul__kopf"><span>{oberVon(m).label}</span><span>Unterthema · Modul {m.id}</span><span>Quelle: AO Einheit {m.einheit} · S. {m.sourcePages.join(", ")}</span><PrioBadge prio={prioInhalt(m)} stopPropagation/></div><h3>{m.title}</h3><div className="modul__norm">{m.law}</div><AOSchemaVerweise text={m.law} onOpen={schemaOeffnen} compact stopPropagation/></div><span className="modul__an">öffnen →</span></div>})}</div>{liste.length===0&&<p className="panel">Keine Treffer.</p>}</>}
function AOOriginalfaelle({oeffnen,schemaOeffnen}){return <><div className="pagehead"><div><span className="kicker">Klausur 1 · Abgabenordnung · Originalfälle</span><h1>Originalfälle der AO-Mitschriften</h1><p className="lead">Kursinterne Aufgaben aus den AO-Einheiten; Tabellen-, Rechen-, Personen- und Zeitachsenfälle werden in ihrer Quellenform dargestellt.</p></div><span className="zaehler">{AO_FAELLE.length} Fälle</span></div><div className="kst-faelle">{AO_FAELLE.map(m=><article className="panel kst-fallkarte" key={m.id}><div className="panel__head"><div><span className="kicker">Fall {m.id} · AO Einheit {m.einheit} · PDF-S. {m.sourcePages.join(", ")}</span> <PrioBadge prio={prioInhalt(m)}/><h2>{m.title}</h2></div><button className="btn btn--klein btn--linie" onClick={()=>oeffnen(m.id)}>Fall öffnen</button></div><p className="kst-fallquelle">{m.law}</p><AOSchemaVerweise text={m.law} onOpen={schemaOeffnen} compact/><div className="kst-sachverhalt"><b>Sachverhalt</b><p>{m.example?.facts}</p></div><details><summary>Lösung anzeigen</summary><div className="fall">{m.id===320||m.id===321?<AOFallEinheit2Darstellung fallId={m.id} onSchema={schemaOeffnen}/>:m.id===334?<AOFall334Darstellung onSchema={schemaOeffnen}/>:((m.einheit===5||m.einheit===6||m.einheit===7)&&m.diagram)?<AOSchema id={m.diagram}/>:<><StandardLoesung m={m} schemaOeffnen={schemaOeffnen}/>{m.diagram&&<AOSchema id={m.diagram}/>}</>}<div className="fall__block fall__ergebnis"><b>Ergebnis</b><p>{m.example?.result}</p></div></div></details></article>)}</div></>}
const QUIZ=[["Wo muss der Einspruch fristwahrend eingehen?",["Bei irgendeinem Finanzamt","Bei einer nach § 357 Abs. 2 AO zulässigen Anbringungsstelle","Nur beim Finanzgericht"],1,"Einheit 3 beginnt genau mit dieser Eingangsfrage."],["Was prüft § 350 AO?",["Beschwer / Einspruchsbefugnis","Festsetzungsfrist","Nichtigkeit"],0,"§ 350 AO ist eine Zulässigkeitsstufe."],["Was ist Plan C?",["Klage","Saldierung nach § 177 AO","Außenprüfung"],1,"Einheit 6 baut Plan C als Saldierung nach § 177 AO vollständig aus."],["Welche Dauer zeigt die Quelle für Steuerhinterziehung?",["4 Jahre","5 Jahre","10 Jahre"],2,"Die Merkbilder zeigen bei Steuerhinterziehung die verlängerte 10-Jahres-Frist."],["Wann greift die Anfechtungsbeschränkung § 351 Abs. 1 AO nach Einheit 7?",["Bei jedem Einspruch","Beim Einspruch gegen einen Änderungsbescheid bei unanfechtbarem Vorbescheid","Nur bei Vollstreckung"],1,"Einheit 7 beginnt mit genau dieser Besonderheit."],["Was muss bei § 110 AO nach der Quelle zuerst geprüft werden?",["Krankheit","Ob überhaupt eine gesetzliche Frist versäumt wurde","Ob ein Antrag unterschrieben wurde"],1,"Die Warnkarte der Einheit 7 verlangt zuerst die Fristart."],["Was ist nach AO 8 beim subjektiven Tatbestand Vorsatz?",["Nur Kenntnis","Wissen & Wollen","Jede Fahrlässigkeit"],1,"Die Quelle schreibt ausdrücklich 'Wissen & Wollen'."],["Welche Norm behandelt die leichtfertige Steuerverkürzung?",["§ 378 AO","§ 69 AO","§ 74 AO"],0,"AO 8 grenzt die Leichtfertigkeit als Ordnungswidrigkeit nach § 378 AO ab."],["Was verlangt § 69 AO nach der Quellenlogik zusätzlich zur Pflichtverletzung?",["Nur einen Haftungsbescheid","Verschulden und kausalen Schaden","Eine Selbstanzeige"],1,"Die Haftungskarte trennt Pflichtverletzung, Verschulden und Schaden."],["Was ist der Ausgangspunkt bei mehreren Geschäftsführern?",["Keine Verantwortung","Gesamtverantwortung aller GF","Nur der Steuer-GF haftet immer"],1,"Die A/B-Skizze startet mit Gesamtverantwortung."],["Welches Merkmal hebt die §-71-Karte besonders hervor?",["Steuerhinterziehung zum fremden Vorteil","Eigentum an einer Fabrik","Klagefrist"],0,"Die Quelle markiert 'zum fremden Vorteil' groß."],["Woran knüpft § 74 AO in der Schlussgrafik an?",["Gegenstände, die dem Unternehmen dienen","Nur an Bargeld","Nur an Geschäftsführer"],0,"Die Schlussseiten zeigen C, Fabrik und Überlassung/Vermietung an die Gesellschaft."]];
function AOTraining(){const[i,setI]=useState(0),[a,setA]=useState(null),f=QUIZ[i];return <><div className="pagehead"><div><span className="kicker">Training · AO Einheiten 1–8</span><h1>AO-Schnellcheck</h1><p className="lead">Wiederholung aus den bislang eingearbeiteten {AO_SEITEN} Seiten/Frames.</p></div></div><section className="panel kst-quiz"><span className="kicker">Frage {i+1} / {QUIZ.length}</span><h2>{f[0]}</h2><div className="kst-optionen">{f[1].map((x,j)=><button key={x} className={`kst-option${a===null?"":j===f[2]?" richtig":j===a?" falsch":""}`} onClick={()=>a===null&&setA(j)}>{x}</button>)}</div>{a!==null&&<div className="kst-erklaerung"><p>{f[3]}</p><button className="btn btn--klein" onClick={()=>{setA(null);setI((i+1)%QUIZ.length)}}>Nächste Frage</button></div>}</section></>}
